var t=[{title:`Erwachsene von 18–64 Jahren`,text:`Die Empfehlung der Weltgesundheitsorganisation lautet 150–300 Minuten aerobe Aktivität mit moderater Intensität pro Woche, oder 75–150 Minuten intensive Aktivität, oder eine gleichwertige Mischung aus beidem. Außerdem empfiehlt sie muskelkräftigende Aktivität für alle großen Muskelgruppen an mindestens zwei Tagen pro Woche. Mehr Aktivität kann zusätzliche Vorteile bringen, aber die richtige Menge hängt von deiner Gesundheit und Leistungsfähigkeit ab.`},{title:`Was Intensität bedeutet`,text:`Moderate Aktivität steigert deine Atmung und Herzfrequenz, aber du kannst dich noch unterhalten. Intensive Aktivität macht es schwer, in vollständigen Sätzen zu sprechen. Zügiges Gehen oder leichtes Radfahren zählen als moderat, Laufen oder hartes Radfahren als intensiv. Du kannst die Minuten in Einheiten, die zu deinem Zeitplan passen, über die Woche verteilen, ein langes Training ist also nicht nötig.`},{title:`Ältere Erwachsene und junge Menschen`,text:`Ältere Erwachsene folgen denselben Zielen für Ausdauer und Kraft. Ihnen wird außerdem geraten, wo möglich an mindestens drei Tagen pro Woche Aktivität mit mehreren Komponenten zu machen, die Gleichgewicht und Kraft betont. Für das Alter von 5–17 Jahren empfiehlt die WHO im Wochendurchschnitt mindestens 60 Minuten moderate bis intensive Aktivität pro Tag, mit intensiver Aktivität sowie muskel- und knochenstärkender Aktivität an mindestens drei Tagen pro Woche.`},{title:`Klein anzufangen zählt auch`,text:`Jede Steigerung gegenüber Inaktivität hilft. Zehnminütige Spaziergänge, Treppensteigen und kurze Einheiten zu Hause führen alle in Richtung der empfohlenen Gesamtwerte. Weniger zu sitzen hilft, auch wenn du schon trainierst, und leichte Aktivität kann einen Teil dieser Sitzzeit ersetzen.`},{title:`Beispiel`,text:`Ein Anfänger könnte zwei Ganzkörpertrainings und drei 30-Minuten-Spaziergänge einplanen und die Spaziergänge dann langsam in Richtung des aeroben Ziels verlängern. Verfolge die Gehminuten getrennt von den Kraftsätzen. Die Empfehlungen sind Ziele für ganze Bevölkerungen, du musst also nicht sofort auf die volle Menge springen.`}];var i=[{label:`WHO-Leitlinien 2020`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC9219310/`},{label:`CDC: Hinweise zur Aktivität`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};